export type ParsedOpenPairScheduleInstruction<
  TProgram extends string = typeof CLEARING_PROGRAM_ADDRESS,
  TAccountMetas extends readonly AccountMeta[] = readonly AccountMeta[],
> = {
  programAddress: Address<TProgram>;
  accounts: {
    payer: TAccountMetas[0];
    certificate: TAccountMetas[1];
    allocation: TAccountMetas[2];
    prepared: TAccountMetas[3];
    resolution: TAccountMetas[4];
    systemProgram: TAccountMetas[5];
  };
  data: OpenPairScheduleInstructionData;
};

export function parseOpenPairScheduleInstruction<
  TProgram extends string,
  TAccountMetas extends readonly AccountMeta[],
>(
  instruction: Instruction<TProgram> &
    InstructionWithAccounts<TAccountMetas> &
    InstructionWithData<ReadonlyUint8Array>,
): ParsedOpenPairScheduleInstruction<TProgram, TAccountMetas> {
  if (instruction.accounts.length < 6) {
    throw new SolanaError(
      SOLANA_ERROR__PROGRAM_CLIENTS__INSUFFICIENT_ACCOUNT_METAS,
      {
        actualAccountMetas: instruction.accounts.length,
        expectedAccountMetas: 6,
      },
    );
  }
  let accountIndex = 0;
  const getNextAccount = () => {
    const accountMeta = (instruction.accounts as TAccountMetas)[accountIndex]!;
    accountIndex += 1;
    return accountMeta;
  };
  return {
    programAddress: instruction.programAddress,
    accounts: {
      payer: getNextAccount(),
      certificate: getNextAccount(),
      allocation: getNextAccount(),
      prepared: getNextAccount(),
      resolution: getNextAccount(),
      systemProgram: getNextAccount(),
    },
    data: getOpenPairScheduleInstructionDataDecoder().decode(instruction.data),
  };
}
